(()=>{const copy={"fr": {"landingpages": ["Une page. Un objectif. Passer à l’action.", "Captez l’attention, valorisez votre offre et transformez l’intérêt en prises de contact."], "websites": ["Donnez à votre marque la place qu’elle mérite.", "Présentez votre savoir-faire avec un site qui inspire confiance et donne envie de vous contacter."], "onlineshops": ["Transformez l’envie en achat.", "Mettez vos produits en valeur et facilitez chaque étape, de la découverte au paiement."]}, "de": {"landingpages": ["Eine Seite. Ein Ziel. Der nächste Schritt.", "Wecken Sie Interesse, zeigen Sie den Wert Ihres Angebots und machen Sie daraus konkrete Anfragen."], "websites": ["Geben Sie Ihrer Marke den Auftritt, den sie verdient.", "Zeigen Sie Ihre Expertise mit einer Website, die Vertrauen schafft und zur Kontaktaufnahme einlädt."], "onlineshops": ["Machen Sie aus Interesse einen Kauf.", "Setzen Sie Ihre Produkte in Szene und erleichtern Sie jeden Schritt – vom Entdecken bis zur Zahlung."]}, "en": {"landingpages": ["One page. One goal. Inspire action.", "Capture attention, show the value of your offer and turn interest into enquiries."], "websites": ["Give your brand the presence it deserves.", "Showcase your expertise with a website that builds trust and encourages people to get in touch."], "onlineshops": ["Turn desire into a purchase.", "Showcase your products and make every step effortless, from discovery to checkout."]}, "es": {"landingpages": ["Una página. Un objetivo. Pasar a la acción.", "Capta la atención, destaca tu oferta y convierte el interés en consultas."], "websites": ["Dale a tu marca la presencia que merece.", "Muestra tu experiencia con una web que inspire confianza y anime a contactar contigo."], "onlineshops": ["Convierte el deseo en una compra.", "Destaca tus productos y facilita cada paso, desde el descubrimiento hasta el pago."]}, "it": {"landingpages": ["Una pagina. Un obiettivo. Passare all’azione.", "Cattura l’attenzione, valorizza la tua offerta e trasforma l’interesse in richieste di contatto."], "websites": ["Dai al tuo marchio la presenza che merita.", "Mostra la tua competenza con un sito che ispira fiducia e invita a contattarti."], "onlineshops": ["Trasforma il desiderio in acquisto.", "Valorizza i tuoi prodotti e semplifica ogni passaggio, dalla scoperta al pagamento."]}};function update(){const t=copy[document.documentElement.lang.slice(0,2)]||copy.de;document.querySelectorAll('[data-demo-title]').forEach(e=>e.textContent=t[e.dataset.demoTitle][0]);document.querySelectorAll('[data-demo-copy]').forEach(e=>e.textContent=t[e.dataset.demoCopy][1]);}update();new MutationObserver(update).observe(document.documentElement,{attributes:true,attributeFilter:['lang']});})();